"""Parse a `Range: bytes=...` header into structured byte ranges.

This module only PARSES the syntax; it does not know the representation length,
so it cannot decide satisfiability. Resolving/clamping against the actual body
length happens in `content.py`.
"""


class ByteRange:
    """A single requested range.

    Exactly one of two forms:
      - explicit:   first is an int >= 0; last is an int >= first, or None for
                    an open-ended `first-` range.
      - suffix:     first is None; suffix_length is a positive int for a
                    `-N` (last N bytes) range.
    """

    def __init__(self, first=None, last=None, suffix_length=None):
        self.first = first
        self.last = last
        self.suffix_length = suffix_length

    def is_suffix(self):
        return self.first is None and self.suffix_length is not None

    def __repr__(self):
        if self.is_suffix():
            return "ByteRange(suffix=%d)" % self.suffix_length
        return "ByteRange(first=%r, last=%r)" % (self.first, self.last)


def parse_range_header(value):
    """Parse a `Range` header value into a list of ByteRange, or None.

    Returns None when the header is absent, does not use the `bytes` unit, or is
    syntactically malformed (the caller then ignores it and serves 200). An
    empty list is never returned: a syntactically valid header has >= 1 range.
    """
    if not value:
        return None
    value = value.strip()
    if "=" not in value:
        return None
    unit, _, spec = value.partition("=")
    if unit.strip().lower() != "bytes":
        return None

    ranges = []
    for part in spec.split(","):
        part = part.strip()
        if not part or "-" not in part:
            return None
        start_txt, _, end_txt = part.partition("-")
        start_txt, end_txt = start_txt.strip(), end_txt.strip()

        if start_txt == "":
            # suffix range: -N
            if not end_txt.isdigit():
                return None
            n = int(end_txt)
            if n == 0:
                return None
            ranges.append(ByteRange(suffix_length=n))
            continue

        if not start_txt.isdigit():
            return None
        first = int(start_txt)

        if end_txt == "":
            ranges.append(ByteRange(first=first, last=None))
        else:
            if not end_txt.isdigit():
                return None
            last = int(end_txt)
            if last < first:
                return None
            ranges.append(ByteRange(first=first, last=last))

    return ranges or None

"""Case-insensitive header container and comma-list parsing."""


class Headers:
    """A minimal case-insensitive multi-map for HTTP headers."""

    def __init__(self, items=None):
        self._store = {}  # lower_name -> (original_name, [values])
        if items:
            for name, value in (items.items() if hasattr(items, "items") else items):
                self.add(name, value)

    def add(self, name, value):
        key = name.lower()
        if key in self._store:
            self._store[key][1].append(value)
        else:
            self._store[key] = (name, [value])

    def get(self, name, default=None):
        entry = self._store.get(name.lower())
        if not entry:
            return default
        return entry[1][0]

    def get_all(self, name):
        entry = self._store.get(name.lower())
        return list(entry[1]) if entry else []

    def __contains__(self, name):
        return name.lower() in self._store

    def __repr__(self):
        return "Headers(%r)" % {v[0]: v[1] for v in self._store.values()}


def parse_list(value):
    """Split a comma-separated header value into trimmed, non-empty tokens."""
    if value is None:
        return []
    return [tok.strip() for tok in value.split(",") if tok.strip()]

"""Response age and freshness-lifetime computation."""
from .datefmt import parse_http_date


def response_age(headers, now, response_time):
    """Estimate a cached response's current age in seconds.

    Uses the explicit `Age` header if present, plus the time elapsed since the
    response was received (`now - response_time`). Never negative.
    """
    age = 0
    age_header = headers.get("Age")
    if age_header is not None:
        try:
            age = max(0, int(age_header.strip()))
        except ValueError:
            age = 0
    resident = now - response_time
    if resident < 0:
        resident = 0
    return age + resident


def freshness_lifetime(headers, date_time=None):
    """Compute how long (seconds) the response stays fresh.

    Prefers `Cache-Control: max-age`; falls back to `Expires - Date`. Returns 0
    if neither is available (i.e. treat as stale and revalidate).
    """
    cc = headers.get("Cache-Control")
    if cc:
        for token in cc.split(","):
            token = token.strip().lower()
            if token.startswith("max-age="):
                try:
                    return max(0, int(token[len("max-age="):]))
                except ValueError:
                    return 0
    expires = parse_http_date(headers.get("Expires"))
    if expires is not None:
        base = date_time if date_time is not None else parse_http_date(headers.get("Date"))
        if base is not None:
            return max(0, expires - base)
    return 0


def is_fresh(headers, now, response_time, date_time=None):
    """A response is fresh iff its age is strictly less than its lifetime."""
    return response_age(headers, now, response_time) < freshness_lifetime(headers, date_time)

"""RFC 7231 IMF-fixdate handling (the one preferred HTTP date format)."""
import calendar
import time

_IMF = "%a, %d %b %Y %H:%M:%S GMT"


def parse_http_date(text):
    """Parse an IMF-fixdate string into a POSIX timestamp (UTC), or None."""
    if not text:
        return None
    try:
        tm = time.strptime(text.strip(), _IMF)
    except ValueError:
        return None
    return calendar.timegm(tm)


def format_http_date(timestamp):
    """Format a POSIX timestamp as an IMF-fixdate string."""
    return time.strftime(_IMF, time.gmtime(timestamp))
